// Batch 4's migrations after engine's 0030_view_as_commission_void: 0031 crew_login (fix-s, crew scope) and 0032
// job_assignee (fix-t, several people per job). Both branches made theirs as idx 31 on the same engine; put together,
// fix-t's was regenerated by drizzle-kit on top of 0031 (idx 32, a later stamp, its snapshot's parent 0031's).
//
// Drizzle applies by TIMESTAMP, so the order of the stamps is held here, and a database that stopped at 0030 holding
// rows is migrated through both and keeps them.
import { describe, test, expect } from 'bun:test'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { PGlite } from '@electric-sql/pglite'
import { drizzle } from 'drizzle-orm/pglite'
import { migrate } from 'drizzle-orm/pglite/migrator'
import { MIGRATIONS } from '../server/db/migrate.ts'

const journal = () => JSON.parse(fs.readFileSync(path.join(MIGRATIONS, 'meta/_journal.json'), 'utf8'))
const snapshot = (idx: number) => JSON.parse(fs.readFileSync(path.join(MIGRATIONS, `meta/${String(idx).padStart(4, '0')}_snapshot.json`), 'utf8'))
const ALL = journal().entries.length
const columns = async (client: PGlite, table: string) =>
  ((await client.query<{ column_name: string }>(`SELECT column_name FROM information_schema.columns WHERE table_name = $1`, [table])).rows).map((r) => r.column_name)
const applied = async (client: PGlite) => Number((await client.query<{ n: number }>(`SELECT count(*)::int AS n FROM drizzle.__drizzle_migrations`)).rows[0].n)

/** The migrations folder as it stood at `last` (its journal cut there), in a temporary folder. */
function upTo(last: number) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'mig-b4-'))
  fs.mkdirSync(path.join(dir, 'meta'))
  const j = journal()
  j.entries = j.entries.filter((e: any) => e.idx <= last)
  for (const e of j.entries) fs.copyFileSync(path.join(MIGRATIONS, `${e.tag}.sql`), path.join(dir, `${e.tag}.sql`))
  fs.writeFileSync(path.join(dir, 'meta/_journal.json'), JSON.stringify(j))
  return dir
}

/** A row with every column the table insists on, filled plainly (the table as it stood at that migration). */
async function insertFilled(client: PGlite, table: string, values: Record<string, unknown>) {
  const required = (await client.query<{ column_name: string; data_type: string }>(
    `SELECT column_name, data_type FROM information_schema.columns WHERE table_name = $1 AND is_nullable = 'NO' AND column_default IS NULL`, [table])).rows
  for (const c of required) if (!(c.column_name in values)) values[c.column_name] = /timestamp|date/.test(c.data_type) ? new Date().toISOString() : /int|numeric|double|real/.test(c.data_type) ? 0 : /bool/.test(c.data_type) ? false : /json/.test(c.data_type) ? '{}' : `x-${c.column_name}`
  const keys = Object.keys(values)
  await client.query(`INSERT INTO "${table}" (${keys.map((k) => `"${k}"`).join(', ')}) VALUES (${keys.map((_, i) => `$${i + 1}`).join(', ')})`, Object.values(values))
}

describe('batch 4 migration chain, 0030 to 0032', () => {
  test('the journal runs 0030, 0031_crew_login, 0032_job_assignee in that order, each stamped after the one before', () => {
    const entries = journal().entries
    expect(entries.map((e: any) => `${e.idx}:${e.tag}`).slice(30, 33)).toEqual(['30:0030_view_as_commission_void', '31:0031_crew_login', '32:0032_job_assignee'])
    expect(entries.map((e: any) => e.idx)).toEqual(entries.map((_: any, i: number) => i))
    for (const e of entries) expect(Number(e.tag.slice(0, 4))).toBe(e.idx)
    for (let i = 1; i < entries.length; i++) expect(entries[i].when).toBeGreaterThan(entries[i - 1].when)
  })

  test('each snapshot names the one before it, and the last carries both new tables', () => {
    const entries = journal().entries
    for (const e of entries) {
      expect(fs.existsSync(path.join(MIGRATIONS, `${e.tag}.sql`))).toBe(true)
      expect(fs.existsSync(path.join(MIGRATIONS, `meta/${String(e.idx).padStart(4, '0')}_snapshot.json`))).toBe(true)
    }
    for (let i = 1; i < entries.length; i++) expect(snapshot(i).prevId).toBe(snapshot(i - 1).id)
    expect(snapshot(31).tables['public.crew_login']).toBeDefined()
    expect(snapshot(31).tables['public.job_assignee']).toBeUndefined()
    const last = snapshot(32).tables
    expect(Object.keys(last['public.crew_login'].columns)).toEqual(expect.arrayContaining(['user_id', 'crew_id', 'team_member_id']))
    expect(Object.keys(last['public.job_assignee'].columns)).toEqual(expect.arrayContaining(['job_id', 'user_id', 'member_id', 'position']))
  })

  test('a database at 0030 holding rows migrates on through 0032, keeps them, takes crew and assignee rows, and a re-run changes nothing', async () => {
    const client = new PGlite()
    await migrate(drizzle(client), { migrationsFolder: upTo(30) })
    expect(await applied(client)).toBe(31)
    expect(await columns(client, 'crew_login')).toEqual([])
    expect(await columns(client, 'job_assignee')).toEqual([])
    await client.exec(`INSERT INTO company (id, name, slug) VALUES ('co1', 'Old Co', 'old-co');`)
    await insertFilled(client, 'user', { id: 'u1', company_id: 'co1', email: 'lead@example.com', first_name: 'Lee' })
    await insertFilled(client, 'user', { id: 'u2', company_id: 'co1', email: 'help@example.com', first_name: 'Hal' })
    await insertFilled(client, 'team_member', { id: 'tm1', company_id: 'co1', name: 'Crew A' })
    await insertFilled(client, 'crew', { id: 'cr1', company_id: 'co1', name: 'Roof crew' })
    await insertFilled(client, 'job', { id: 'j1', company_id: 'co1', number: 'JOB-1', title: 'Mow', assigned_to_id: 'u1' })

    await migrate(drizzle(client), { migrationsFolder: MIGRATIONS })
    expect(await applied(client)).toBe(ALL)
    // The old rows are untouched.
    expect((await client.query<any>(`SELECT number, title, assigned_to_id FROM job WHERE id = 'j1'`)).rows[0]).toEqual({ number: 'JOB-1', title: 'Mow', assigned_to_id: 'u1' })
    expect((await client.query<any>(`SELECT count(*)::int AS n FROM "user"`)).rows[0].n).toBe(2)
    // 0031: a login goes on a roster crew and a roofing crew; 0032: a second person goes on the job.
    await client.exec(`
      INSERT INTO crew_login (id, company_id, user_id, team_member_id) VALUES ('cl1', 'co1', 'u2', 'tm1');
      INSERT INTO crew_login (id, company_id, user_id, crew_id) VALUES ('cl2', 'co1', 'u2', 'cr1');
      INSERT INTO job_assignee (id, company_id, job_id, user_id, position) VALUES ('ja1', 'co1', 'j1', 'u2', 1);
    `)
    // The unique pairs hold: the same login twice on one crew, or the same person twice on one job, is refused.
    await expect(client.exec(`INSERT INTO crew_login (id, company_id, user_id, team_member_id) VALUES ('cl3', 'co1', 'u2', 'tm1')`)).rejects.toThrow()
    await expect(client.exec(`INSERT INTO job_assignee (id, company_id, job_id, user_id) VALUES ('ja2', 'co1', 'j1', 'u2')`)).rejects.toThrow()
    // Deleting the job takes its assignee rows with it; deleting the crew takes its logins.
    await client.exec(`DELETE FROM job WHERE id = 'j1'; DELETE FROM team_member WHERE id = 'tm1';`)
    expect((await client.query<any>(`SELECT count(*)::int AS n FROM job_assignee`)).rows[0].n).toBe(0)
    expect((await client.query<any>(`SELECT id FROM crew_login`)).rows).toEqual([{ id: 'cl2' }])

    // A second run applies nothing.
    await migrate(drizzle(client), { migrationsFolder: MIGRATIONS })
    expect(await applied(client)).toBe(ALL)
    await client.close()
  }, 180_000)
})
